const r = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && rg --files -g 'AGENTS.md' -g '!**/.git/**' -g 'checkpoint.md' -g '!**/.codex-role-output/**' | head -80",workdir:"/app",max_output_tokens:2000}),
  tools.exec_command({cmd:"git status --short && rg -n 'TextBrightnessThreshold|ForegroundBrightnessThreshold|darkmode.threshold.text' . --glob '!**/.git/**'",workdir:"/app",max_output_tokens:6000})
]); for (const x of r) text(x);

const r=await Promise.allSettled([
  tools.exec_command({cmd:"find .. -name AGENTS.md -print",workdir:"/app",max_output_tokens:2000}),
  tools.exec_command({cmd:"ls -la && git status --short && grep -R -n -E 'TextBrightnessThreshold|ForegroundBrightnessThreshold|darkmode\\.threshold\\.text' . --exclude-dir=.git",workdir:"/app",max_output_tokens:8000})
]); for(const x of r) text(x);

const r=await Promise.allSettled([
 tools.exec_command({cmd:"cat .codex-role-output/checkpoint.md",workdir:"/app",max_output_tokens:2000}),
 tools.exec_command({cmd:"sed -n '1,330p' qutebrowser/browser/webengine/darkmode.py && sed -n '1,240p' tests/unit/browser/webengine/test_darkmode.py",workdir:"/app",max_output_tokens:12000})
]); for (const x of r) text(x);

const r=await Promise.allSettled([
 tools.exec_command({cmd:"sed -n '330,680p' qutebrowser/browser/webengine/darkmode.py && sed -n '240,520p' tests/unit/browser/webengine/test_darkmode.py",workdir:"/app",max_output_tokens:12000}),
 tools.exec_command({cmd:"find tests -maxdepth 3 -name 'conftest.py' -print && sed -n '1,180p' pytest.ini && git status --short",workdir:"/app",max_output_tokens:6000})
]); for(const x of r) text(x);

const r=await Promise.allSettled([
 tools.exec_command({cmd:"QT_QPA_PLATFORM=offscreen python -m pytest -q tests/unit/browser/webengine/test_darkmode.py",workdir:"/app",yield_time_ms:30000,max_output_tokens:6000}),
 tools.exec_command({cmd:"git diff --check && git diff -- qutebrowser/browser/webengine/darkmode.py tests/unit/browser/webengine/test_darkmode.py && git status --short",workdir:"/app",max_output_tokens:8000})
]); for(const x of r) text(x);

const r=await Promise.allSettled([
 tools.exec_command({cmd:"grep -R -n 'Variant.qt_\\|QUTE_DARKMODE_VARIANT' qutebrowser tests/unit/browser/webengine --exclude='*.pyc'",workdir:"/app",max_output_tokens:6000}),
 tools.exec_command({cmd:"find .codex-role-output -maxdepth 1 -type f -print && git status --short --untracked-files=all && git check-ignore -v .codex-role-output/checkpoint.md",workdir:"/app",max_output_tokens:2000})
]); for(const x of r) text(x);
